#include <vector>
#include <cstddef>
#include <algorithm>
#include <omp.h>

size_t findFirstEven(std::vector<int> const& x) {
    const size_t n = x.size();
    if (n == 0) return n; // not found

    size_t best = n;

#pragma omp parallel
    {
        size_t localBest = n;

#pragma omp for nowait
        for (size_t i = 0; i < n; ++i) {
            if ((x[i] % 2) == 0) {
                if (i < localBest) localBest = i;
            }
        }

#pragma omp critical
        {
            if (localBest < best) best = localBest;
        }
    }

    return best; // returns x.size() if no even number exists
}
